page_settings.custom_css:
/* =========================================================
   Yogi's VPS Archive Template
   Dark archive styling for Elementor Theme Builder
   ========================================================= */

:root{
  --yvps-bg: #060b16;
  --yvps-bg-alt: #0b1220;
  --yvps-surface: #0f172a;
  --yvps-surface-2: #131d33;
  --yvps-border: rgba(255,255,255,0.08);
  --yvps-border-strong: rgba(56,189,248,0.22);
  --yvps-text: #e5eefc;
  --yvps-muted: #94a3b8;
  --yvps-blue: #38bdf8;
  --yvps-blue-2: #0ea5e9;
  --yvps-glow: 0 0 0 1px rgba(56,189,248,0.08), 0 20px 50px rgba(2,8,23,0.6);
  --yvps-radius: 20px;
  --yvps-radius-sm: 14px;
  --yvps-max: 1280px;
}

/* Page background */
body.post-type-archive,
body.archive,
body.blog {
  background:
    radial-gradient(circle at top left, rgba(56,189,248,0.10), transparent 28%),
    radial-gradient(circle at top right, rgba(14,165,233,0.08), transparent 24%),
    linear-gradient(180deg, #08111f 0%, #050914 100%);
  color: var(--yvps-text);
}

/* Main Elementor archive wrapper */
.elementor-location-archive {
  color: var(--yvps-text);
}

/* Constrain top-level sections */
.elementor-location-archive .e-con,
.elementor-location-archive .elementor-section,
.elementor-location-archive .elementor-container {
  box-sizing: border-box;
}

/* Hero / archive heading area */
.elementor-location-archive .elementor-widget-theme-archive-title,
.elementor-location-archive .elementor-widget-heading {
  position: relative;
}

.elementor-location-archive .elementor-widget-theme-archive-title .elementor-heading-title,
.elementor-location-archive .elementor-widget-heading .elementor-heading-title {
  color: #f8fbff;
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.05;
}

.elementor-location-archive .elementor-widget-text-editor,
.elementor-location-archive .elementor-widget-text-editor p {
  color: var(--yvps-muted);
  line-height: 1.75;
}

/* Make top intro area feel premium */
.elementor-location-archive .elementor-top-section:first-child,
.elementor-location-archive > .e-con:first-child {
  position: relative;
}

.elementor-location-archive .elementor-top-section:first-child::before,
.elementor-location-archive > .e-con:first-child::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 24px;
  background:
    linear-gradient(180deg, rgba(15,23,42,0.85), rgba(7,12,24,0.82));
  border: 1px solid rgba(255,255,255,0.06);
  box-shadow: var(--yvps-glow);
  pointer-events: none;
}

/* Search form */
.elementor-location-archive .elementor-search-form {
  background: rgba(15,23,42,0.75);
  border: 1px solid var(--yvps-border);
  border-radius: 999px;
  padding: 8px;
  box-shadow: var(--yvps-glow);
  backdrop-filter: blur(10px);
}

.elementor-location-archive .elementor-search-form__input {
  background: transparent !important;
  color: #fff !important;
  border: 0 !important;
  box-shadow: none !important;
  padding-left: 16px !important;
  font-size: 15px;
}

.elementor-location-archive .elementor-search-form__input::placeholder {
  color: #8da0bc !important;
}

.elementor-location-archive .elementor-search-form__submit {
  border-radius: 999px !important;
  background: linear-gradient(135deg, var(--yvps-blue), var(--yvps-blue-2)) !important;
  color: #04111f !important;
  border: 0 !important;
  font-weight: 700;
  padding: 0 20px !important;
  transition: transform .2s ease, box-shadow .2s ease, opacity .2s ease;
}

.elementor-location-archive .elementor-search-form__submit:hover {
  transform: translateY(-1px);
  box-shadow: 0 12px 30px rgba(14,165,233,0.28);
  opacity: 0.96;
}

/* Archive posts grid wrapper */
.elementor-location-archive .elementor-widget-archive-posts,
.elementor-location-archive .elementor-widget-posts {
  position: relative;
}

/* Card styling for Elementor post/archive skins */
.elementor-location-archive .elementor-post,
.elementor-location-archive article.post,
.elementor-location-archive .e-loop-item {
  background: linear-gradient(180deg, rgba(17,24,39,0.98), rgba(10,15,28,0.98));
  border: 1px solid var(--yvps-border);
  border-radius: var(--yvps-radius);
  overflow: hidden;
  box-shadow: 0 18px 45px rgba(0,0,0,0.35);
  transition: transform .28s ease, box-shadow .28s ease, border-color .28s ease;
}

.elementor-location-archive .elementor-post:hover,
.elementor-location-archive article.post:hover,
.elementor-location-archive .e-loop-item:hover {
  transform: translateY(-6px);
  border-color: var(--yvps-border-strong);
  box-shadow:
    0 0 0 1px rgba(56,189,248,0.12),
    0 28px 60px rgba(2,8,23,0.72);
}

/* Featured images */
.elementor-location-archive .elementor-post__thumbnail,
.elementor-location-archive .elementor-post__thumbnail img,
.elementor-location-archive .elementor-image-box-img img,
.elementor-location-archive article.post img {
  display: block;
  width: 100%;
}

.elementor-location-archive .elementor-post__thumbnail {
  overflow: hidden;
  background: #0b1220;
}

.elementor-location-archive .elementor-post__thumbnail img,
.elementor-location-archive article.post img {
  aspect-ratio: 16 / 9;
  object-fit: cover;
  transition: transform .45s ease, opacity .3s ease;
}

.elementor-location-archive .elementor-post:hover .elementor-post__thumbnail img,
.elementor-location-archive article.post:hover img {
  transform: scale(1.04);
  opacity: 0.95;
}

/* Post content area */
.elementor-location-archive .elementor-post__text,
.elementor-location-archive .elementor-post__card .elementor-post__text,
.elementor-location-archive .e-loop-item > *:not(img) {
  padding: 22px 22px 24px;
}

/* Post title */
.elementor-location-archive .elementor-post__title,
.elementor-location-archive .elementor-post__title a,
.elementor-location-archive article.post .entry-title,
.elementor-location-archive article.post .entry-title a {
  font-size: clamp(1.15rem, 1.05rem + 0.3vw, 1.45rem);
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: -0.02em;
  text-decoration: none;
}

.elementor-location-archive .elementor-post__title a:hover,
.elementor-location-archive article.post .entry-title a:hover {
  color: var(--yvps-blue) !important;
}

/* Excerpt */
.elementor-location-archive .elementor-post__excerpt,
.elementor-location-archive .elementor-post__excerpt p,
.elementor-location-archive article.post .entry-excerpt,
.elementor-location-archive article.post .entry-summary {
  color: var(--yvps-muted) !important;
  font-size: 0.98rem;
  line-height: 1.75;
}

/* Meta */
.elementor-location-archive .elementor-post__meta-data,
.elementor-location-archive .elementor-post-info,
.elementor-location-archive .elementor-icon-list-text,
.elementor-location-archive .elementor-post-date,
.elementor-location-archive .elementor-post-author {
  color: #8ea3bf !important;
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

/* Read more button */
.elementor-location-archive .elementor-post__read-more,
.elementor-location-archive a.elementor-post__read-more {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 14px;
  padding: 12px 16px;
  border-radius: 999px;
  background: rgba(56,189,248,0.08);
  border: 1px solid rgba(56,189,248,0.18);
  color: #bfeaff !important;
  font-weight: 700;
  text-decoration: none !important;
  transition: all .22s ease;
}

.elementor-location-archive .elementor-post__read-more:hover,
.elementor-location-archive a.elementor-post__read-more:hover {
  background: linear-gradient(135deg, var(--yvps-blue), var(--yvps-blue-2));
  color: #04111f !important;
  border-color: transparent;
  transform: translateY(-1px);
}

/* Sidebar widgets */
.elementor-location-archive .elementor-widget-sidebar .widget,
.elementor-location-archive aside .widget {
  background: linear-gradient(180deg, rgba(15,23,42,0.94), rgba(9,14,26,0.96));
  border: 1px solid var(--yvps-border);
  border-radius: 18px;
  padding: 22px;
  margin-bottom: 22px;
  box-shadow: var(--yvps-glow);
}

.elementor-location-archive .elementor-widget-sidebar .widget-title,
.elementor-location-archive aside .widget-title,
.elementor-location-archive aside h2 {
  color: #f8fbff;
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 14px;
}

/* Sidebar links */
.elementor-location-archive .elementor-widget-sidebar a,
.elementor-location-archive aside a {
  color: #c7d8ee;
  text-decoration: none;
  transition: color .2s ease, padding-left .2s ease;
}

.elementor-location-archive .elementor-widget-sidebar a:hover,
.elementor-location-archive aside a:hover {
  color: var(--yvps-blue);
  padding-left: 3px;
}

/* Categories / lists */
.elementor-location-archive .widget ul,
.elementor-location-archive aside ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.elementor-location-archive .widget li,
.elementor-location-archive aside li {
  border-bottom: 1px solid rgba(255,255,255,0.06);
  padding: 10px 0;
}

.elementor-location-archive .widget li:last-child,
.elementor-location-archive aside li:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

/* CTA boxes if you add text editor/button widgets */
.elementor-location-archive .yvps-archive-cta,
.elementor-location-archive .elementor-widget-button.yvps-archive-cta-wrap,
.elementor-location-archive .yvps-dark-panel {
  background:
    radial-gradient(circle at top left, rgba(56,189,248,0.12), transparent 42%),
    linear-gradient(180deg, #0d1426, #08101f);
  border: 1px solid rgba(56,189,248,0.18);
  border-radius: 22px;
  padding: 24px;
  box-shadow:
    0 0 0 1px rgba(56,189,248,0.08),
    0 24px 55px rgba(0,0,0,0.45);
}

.elementor-location-archive .elementor-button,
.elementor-location-archive .yvps-btn {
  border-radius: 999px !important;
  font-weight: 800 !important;
  letter-spacing: 0.01em;
  padding: 14px 20px !important;
  background: linear-gradient(135deg, var(--yvps-blue), var(--yvps-blue-2)) !important;
  color: #04111f !important;
  border: 0 !important;
  box-shadow: 0 14px 30px rgba(14,165,233,0.25);
  transition: transform .2s ease, box-shadow .2s ease, opacity .2s ease;
}

.elementor-location-archive .elementor-button:hover,
.elementor-location-archive .yvps-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 18px 38px rgba(14,165,233,0.32);
  opacity: 0.97;
}

/* Pagination */
.elementor-location-archive .elementor-pagination,
.elementor-location-archive .page-numbers,
.elementor-location-archive nav.pagination {
  margin-top: 26px;
}

.elementor-location-archive .page-numbers,
.elementor-location-archive .elementor-pagination a,
.elementor-location-archive .elementor-pagination span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  height: 44px;
  padding: 0 14px;
  border-radius: 999px;
  border: 1px solid var(--yvps-border);
  background: rgba(15,23,42,0.84);
  color: #d9e8fb !important;
  text-decoration: none !important;
  margin: 0 6px 6px 0;
  transition: all .2s ease;
}

.elementor-location-archive .page-numbers:hover,
.elementor-location-archive .elementor-pagination a:hover,
.elementor-location-archive .elementor-pagination span.current,
.elementor-location-archive .page-numbers.current {
  background: linear-gradient(135deg, var(--yvps-blue), var(--yvps-blue-2));
  color: #04111f !important;
  border-color: transparent;
}

/* Empty states */
.elementor-location-archive .elementor-posts-nothing-found,
.elementor-location-archive .nothing-found,
.elementor-location-archive .no-results {
  background: rgba(15,23,42,0.9);
  border: 1px solid var(--yvps-border);
  border-radius: 20px;
  padding: 26px;
  color: var(--yvps-muted);
}

/* Nice spacing between archive sections */
.elementor-location-archive .elementor-widget:not(:last-child),
.elementor-location-archive .widget:not(:last-child) {
  margin-bottom: 20px;
}

/* Links in content */
.elementor-location-archive a {
  transition: color .2s ease, opacity .2s ease;
}

.elementor-location-archive a:hover {
  opacity: 1;
}

/* Responsive */
@media (max-width: 1024px) {
  .elementor-location-archive .elementor-post__text,
  .elementor-location-archive .elementor-post__card .elementor-post__text,
  .elementor-location-archive .e-loop-item > *:not(img) {
    padding: 20px;
  }
}

@media (max-width: 767px) {
  .elementor-location-archive .elementor-post,
  .elementor-location-archive article.post,
  .elementor-location-archive .e-loop-item,
  .elementor-location-archive .elementor-widget-sidebar .widget,
  .elementor-location-archive aside .widget {
    border-radius: 16px;
  }

  .elementor-location-archive .elementor-search-form {
    border-radius: 18px;
  }

  .elementor-location-archive .elementor-search-form__submit {
    padding: 0 16px !important;
  }

  .elementor-location-archive .elementor-post__title,
  .elementor-location-archive .elementor-post__title a,
  .elementor-location-archive article.post .entry-title,
  .elementor-location-archive article.post .entry-title a {
    font-size: 1.15rem;
  }
}

/* Desktop sticky right column */
@media (min-width: 1025px) {
  .elementor-location-single .e-con,
  .elementor-location-single .elementor-container,
  .elementor-location-single .elementor-section-wrap {
    align-items: flex-start;
  }

  /* Right column wrapper */
  .elementor-location-single .yvps-sticky-sidebar,
  .elementor-location-single .sticky-sidebar,
  .elementor-location-single .elementor-column.yvps-sticky-sidebar,
  .elementor-location-single .elementor-element.yvps-sticky-sidebar {
    position: sticky;
    top: 110px;
    align-self: flex-start;
  }
}

/* =========================================================
   Yogi's VPS Archive Card Refinements
   Fix white card interior + tighten spacing
   ========================================================= */

/* Tighter overall posts widget spacing */
.elementor-location-archive .elementor-widget-archive-posts,
.elementor-location-archive .elementor-widget-posts {
  margin-bottom: 0 !important;
}

.elementor-location-archive .elementor-posts-container,
.elementor-location-archive .elementor-loop-container {
  gap: 26px !important;
}

/* Force full dark card shell */
.elementor-location-archive .elementor-post,
.elementor-location-archive article.post,
.elementor-location-archive .e-loop-item,
.elementor-location-archive .elementor-post__card {
  background: linear-gradient(180deg, #0d1728 0%, #0a1322 100%) !important;
  border: 1px solid rgba(255,255,255,0.08) !important;
  border-radius: 22px !important;
  overflow: hidden !important;
  box-shadow:
    0 18px 40px rgba(0,0,0,0.34),
    0 0 0 1px rgba(56,189,248,0.06) !important;
}

/* Remove white inner content blocks Elementor sometimes injects */
.elementor-location-archive .elementor-post__text,
.elementor-location-archive .elementor-post__card .elementor-post__text,
.elementor-location-archive .elementor-post__card .elementor-post__badge,
.elementor-location-archive .elementor-post__card .elementor-post__meta-data,
.elementor-location-archive .elementor-post__card .elementor-post__excerpt,
.elementor-location-archive .elementor-post__card .elementor-post__read-more,
.elementor-location-archive .elementor-post__card .elementor-post__title,
.elementor-location-archive .elementor-post__card .elementor-post__title a {
  background: transparent !important;
}

/* Content section spacing */
.elementor-location-archive .elementor-post__text {
  padding: 20px 22px 16px !important;
}

/* Featured image tighter */
.elementor-location-archive .elementor-post__thumbnail {
  margin: 0 !important;
  line-height: 0;
  background: #09111f !important;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}

.elementor-location-archive .elementor-post__thumbnail img,
.elementor-location-archive article.post img {
  aspect-ratio: 16 / 8.8;
  object-fit: cover;
  min-height: 210px;
}

/* Title spacing and stronger contrast */
.elementor-location-archive .elementor-post__title {
  margin: 0 0 12px !important;
  padding: 0 !important;
  line-height: 1.2 !important;
}

.elementor-location-archive .elementor-post__title a,
.elementor-location-archive article.post .entry-title a {
  color: #eaf6ff !important;
  font-size: clamp(1.1rem, 1rem + 0.4vw, 1.55rem) !important;
  font-weight: 800 !important;
  letter-spacing: -0.025em !important;
}

.elementor-location-archive .elementor-post__title a:hover,
.elementor-location-archive article.post .entry-title a:hover {
  color: #7dd3fc !important;
}

/* Excerpt tightened and more readable */
.elementor-location-archive .elementor-post__excerpt,
.elementor-location-archive .elementor-post__excerpt p,
.elementor-location-archive article.post .entry-excerpt,
.elementor-location-archive article.post .entry-summary {
  margin: 0 !important;
  color: #97a8c0 !important;
  font-size: 0.97rem !important;
  line-height: 1.72 !important;
}

/* Clamp excerpt so cards stay even */
.elementor-location-archive .elementor-post__excerpt,
.elementor-location-archive .elementor-post__excerpt p {
  display: -webkit-box;
  -webkit-line-clamp: 6;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Read more spacing */
.elementor-location-archive .elementor-post__read-more,
.elementor-location-archive a.elementor-post__read-more {
  margin-top: 16px !important;
  padding: 10px 15px !important;
  font-size: 0.78rem !important;
  letter-spacing: 0.04em;
}

/* Meta bar at bottom of card */
.elementor-location-archive .elementor-post__meta-data,
.elementor-location-archive .elementor-post-info {
  margin: 18px 0 0 !important;
  padding: 14px 22px 16px !important;
  border-top: 1px solid rgba(255,255,255,0.07);
  background: linear-gradient(180deg, rgba(255,255,255,0.01), rgba(255,255,255,0.03)) !important;
  color: #8ea3bf !important;
  font-size: 0.78rem !important;
  letter-spacing: 0.08em !important;
}

/* If Elementor places meta inside text area, this helps */
.elementor-location-archive .elementor-post__meta-data span,
.elementor-location-archive .elementor-post-info span,
.elementor-location-archive .elementor-post__meta-data a,
.elementor-location-archive .elementor-post-info a {
  color: #8ea3bf !important;
}

/* Make card hover feel cleaner */
.elementor-location-archive .elementor-post:hover,
.elementor-location-archive article.post:hover,
.elementor-location-archive .e-loop-item:hover,
.elementor-location-archive .elementor-post__card:hover {
  transform: translateY(-5px);
  border-color: rgba(56,189,248,0.18) !important;
  box-shadow:
    0 0 0 1px rgba(56,189,248,0.12),
    0 24px 54px rgba(2,8,23,0.72) !important;
}

/* Sidebar spacing tightened a bit */
.elementor-location-archive .elementor-widget-sidebar .widget,
.elementor-location-archive aside .widget {
  padding: 20px !important;
  margin-bottom: 18px !important;
}

.elementor-location-archive .widget li,
.elementor-location-archive aside li {
  padding: 8px 0 !important;
}

/* Improve right rail topic list */
.elementor-location-archive .widget ul li a,
.elementor-location-archive aside ul li a {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  line-height: 1.45;
}

/* Tighten layout on tablet/mobile */
@media (max-width: 1024px) {
  .elementor-location-archive .elementor-posts-container,
  .elementor-location-archive .elementor-loop-container {
    gap: 20px !important;
  }

  .elementor-location-archive .elementor-post__text {
    padding: 18px 18px 14px !important;
  }

  .elementor-location-archive .elementor-post__meta-data,
  .elementor-location-archive .elementor-post-info {
    padding: 12px 18px 14px !important;
  }
}

@media (max-width: 767px) {
  .elementor-location-archive .elementor-post__thumbnail img,
  .elementor-location-archive article.post img {
    min-height: 180px;
  }

  .elementor-location-archive .elementor-post__excerpt,
  .elementor-location-archive .elementor-post__excerpt p {
    -webkit-line-clamp: 5;
  }
}
